class HotelOwnerManageScreen extends StatefulWidget{const HotelOwnerManageScreen({required this.hotel,super.key});final HotelSummary hotel;@override State<HotelOwnerManageScreen>createState()=>_S();}class _S extends State<HotelOwnerManageScreen>{List<Map<String,dynamic>> bookings=[];bool busy=true;@override void didChangeDependencies(){super.didChangeDependencies();if(bookings.isEmpty)_load();}Future<void>_load()async{try{bookings=await HotelRepository(AppControllerScope.of(context).apiClient).ownerBookings(hotelId:widget.hotel.id);}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.hotel.name,style:const TextStyle(fontSize:15))),floatingActionButton:FloatingActionButton.extended(onPressed:_addRoom,icon:const Icon(Icons.bed_rounded),label:const Text('Add room')),body:ListView(padding:const EdgeInsets.all(14),children:[Card(child:ListTile(leading:const Icon(Icons.verified_user_rounded),title:Text('Status: ${widget.hotel.approvalStatus??'Pending'}',style:const TextStyle(fontSize:12,fontWeight:FontWeight.w800)),subtitle:const Text('Only approved hotels are visible to customers.',style:TextStyle(fontSize:9)))),const SizedBox(height:12),const Text('Recent bookings',style:TextStyle(fontSize:14,fontWeight:FontWeight.w900)),const SizedBox(height:7),if(busy)const Center(child:CircularProgressIndicator())else if(bookings.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('No bookings yet.',style:TextStyle(fontSize:11))))else for(final b in bookings)Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.bed_outlined)),title:Text('${b['roomType']} • ${b['rooms']} room',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800)),subtitle:Text('${b['checkIn']} → ${b['checkOut']}\n${b['status']} • ${b['paymentStatus']}',style:const TextStyle(fontSize:9)),isThreeLine:true,trailing:Text('PKR ${b['amount']}',style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900))))]));Future<void>_addRoom()async{final type=TextEditingController(),capacity=TextEditingController(text:'2'),total=TextEditingController(text:'1'),rate=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Add room type'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:type,decoration:const InputDecoration(labelText:'Room type')),TextField(controller:capacity,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Guest capacity')),TextField(controller:total,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Total rooms')),TextField(controller:rate,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Base rate per night'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Add'))]))??false;if(!ok||type.text.trim().isEmpty)return;await HotelRepository(AppControllerScope.of(context).apiClient).addRoom(widget.hotel.id,{'roomType':type.text.trim(),'description':'','capacity':int.tryParse(capacity.text)??2,'totalRooms':int.tryParse(total.text)??1,'baseRate':double.tryParse(rate.text)??0,'imageUrl':'','amenities':<String>[]});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Room type added.')));}}
